/* Acota un valor al rango [lo, hi]; protege contra NaN devolviendo lo. */
static inline double terrain_dem_clamp(double val, double lo, double hi) {
    if (!(val >= lo)) return lo;
    if (val > hi) return hi;
    return val;
}

/* Interpolacion bilineal en double sobre s_demGrid[64][64] para (lat, lon). */
static inline double terrain_dem_bilinear(double lat, double lon) {
    double span_lon = TERRAIN_DEM_MAX_LON - TERRAIN_DEM_MIN_LON;
    double span_lat = TERRAIN_DEM_MAX_LAT - TERRAIN_DEM_MIN_LAT;
    double u = terrain_dem_clamp((lon - TERRAIN_DEM_MIN_LON) / span_lon * (double)(TERRAIN_DEM_NX - 1), 0.0, (double)(TERRAIN_DEM_NX - 1));
    double v = terrain_dem_clamp((lat - TERRAIN_DEM_MIN_LAT) / span_lat * (double)(TERRAIN_DEM_NY - 1), 0.0, (double)(TERRAIN_DEM_NY - 1));

    int i = (int)u;
    int j = (int)v;
    if (i > TERRAIN_DEM_NX - 2) i = TERRAIN_DEM_NX - 2;
    if (j > TERRAIN_DEM_NY - 2) j = TERRAIN_DEM_NY - 2;

    double du = u - (double)i;
    double dv = v - (double)j;
    double h0 = s_demGrid[j][i] * (1.0 - du) + s_demGrid[j][i + 1] * du;
    double h1 = s_demGrid[j + 1][i] * (1.0 - du) + s_demGrid[j + 1][i + 1] * du;
    return h0 * (1.0 - dv) + h1 * dv;
}

/* Distancia minima punto-segmento y producto cruz 2D sin normalizar (replica _dist_and_side_to_poly). */
static inline double terrain_dem_seg_dist_side(double px, double pz, double ax, double az, double bx, double bz, double *out_side) {
    double dx = bx - ax;
    double dz = bz - az;
    double l_sq = dx * dx + dz * dz;
    if (l_sq < 1e-6) {
        *out_side = 0.0;
        return hypot(px - ax, pz - az);
    }
    double t = terrain_dem_clamp(((px - ax) * dx + (pz - az) * dz) / l_sq, 0.0, 1.0);
    double proj_x = ax + t * dx;
    double proj_z = az + t * dz;
    /* Nota: geo_dem.py usa el producto cruz 2D sin normalizar como argumento de tanh(s / 40.0). */
    *out_side = (px - ax) * dz - (pz - az) * dx;
    return hypot(px - proj_x, pz - proj_z);
}

/* Distancia minima y signo lateral respecto a una polilinea proyectada a coordenadas metricas. */
static inline void terrain_dem_poly_dist_side(double px, double pz, const TerrainDemGeoPt *pts, int count, double m_per_lon, double *out_min_d, double *out_side) {
    double min_d = 1e300;
    double side_val = 0.0;
    for (int k = 0; k < count - 1; k++) {
        double ax = (pts[k].lon - TERRAIN_DEM_ORIGIN_LON) * m_per_lon;
        double az = -(pts[k].lat - TERRAIN_DEM_ORIGIN_LAT) * TERRAIN_DEM_M_PER_LAT;
        double bx = (pts[k + 1].lon - TERRAIN_DEM_ORIGIN_LON) * m_per_lon;
        double bz = -(pts[k + 1].lat - TERRAIN_DEM_ORIGIN_LAT) * TERRAIN_DEM_M_PER_LAT;
        double s = 0.0;
        double d = terrain_dem_seg_dist_side(px, pz, ax, az, bx, bz, &s);
        if (d < min_d) {
            min_d = d;
            side_val = s;
        }
    }
    *out_min_d = min_d;
    if (out_side) *out_side = side_val;
}

/* Depresion parabolica de los 4 cauces fluviales dentro de su ancho de valle. */
static inline double terrain_dem_apply_rivers(double py, double px, double pz, double m_per_lon) {
    int num_rivers = (int)(sizeof(s_demRivers) / sizeof(s_demRivers[0]));
    for (int r = 0; r < num_rivers; r++) {
        double d = 0.0;
        terrain_dem_poly_dist_side(px, pz, s_demRivers[r].coords, s_demRivers[r].count, m_per_lon, &d, (double *)0);
        if (d < s_demRivers[r].valley_w) {
            double f = 1.0 - (d / s_demRivers[r].valley_w);
            py -= s_demRivers[r].depth * (f * f);
        }
    }
    return py;
}

/* Escarpes de las 2 fallas geologicas mediante tanh(s / 40.0) dentro de 120m. */
static inline double terrain_dem_apply_faults(double py, double px, double pz, double m_per_lon) {
    int num_faults = (int)(sizeof(s_demFaults) / sizeof(s_demFaults[0]));
    for (int k = 0; k < num_faults; k++) {
        double d = 0.0;
        double s = 0.0;
        terrain_dem_poly_dist_side(px, pz, s_demFaults[k].coords, s_demFaults[k].count, m_per_lon, &d, &s);
        if (d < 120.0) {
            double t_fault = tanh(s / 40.0) * s_demFaults[k].down_sign;
            py += s_demFaults[k].step * 0.5 * t_fault;
        }
    }
    return py;
}

/* Elevacion topografica real (m) relativa a 1871.0 msnm; replica geo_dem.py::get_real_topography. */
static inline float terrain_dem_get_elevation(float x, float z) {
    double px = (double)x;
    double pz = (double)z;
    double m_per_lon = TERRAIN_DEM_M_PER_LAT * cos(TERRAIN_DEM_ORIGIN_LAT * (M_PI / 180.0));
    double lon = TERRAIN_DEM_ORIGIN_LON + px / m_per_lon;
    double lat = TERRAIN_DEM_ORIGIN_LAT - pz / TERRAIN_DEM_M_PER_LAT;

    double py = terrain_dem_bilinear(lat, lon) - TERRAIN_DEM_BASE_ELEVATION;
    py = terrain_dem_apply_rivers(py, px, pz, m_per_lon);
    py = terrain_dem_apply_faults(py, px, pz, m_per_lon);
    return (float)py;
}

